export default {
  id: "jetpack",
  title: "Jetpack",
  knobs: { fuelMax: { value: 100, min: 20, max: 200, label: "Fuel Max" }, thrust: { value: 1450, min: 500, max: 2500, label: "Thrust" } },
  setup(api: any, knobs: any) {
    const maxFuel = Number(knobs.fuelMax) || 100;
    const thrust = Number(knobs.thrust) || 1450;
    let fuel = maxFuel;
    api.spawn({ type: "jetpack", x: 60, y: 340, w: 24, h: 30, solid: false, gravityScale: 0, color: 0xff8833 });
    api.setHud("jetpack-fuel", { kind: "bar", label: "Jetpack", value: fuel, max: maxFuel, color: 0xff8833, position: "bottom-left" });
    api.onTick((dt: number) => {
      const p = api.player();
      if (p && p.onGround) fuel = Math.min(maxFuel, fuel + 28 * dt);
      if (p && api.input().jump && !p.onGround && fuel > 0) {
        fuel = Math.max(0, fuel - 30 * dt);
        p.vy -= thrust * dt;
        if (p.vy < -380) p.vy = -380;
      }
      api.setHud("jetpack-fuel", { kind: "bar", label: "Jetpack", value: Math.round(fuel), max: maxFuel, color: 0xff8833, position: "bottom-left" });
    });
  },
  dispose(api: any) {
    for (const e of api.byType("jetpack")) api.despawn(e.id);
    api.removeHud("jetpack-fuel");
  },
  test(t: any) {
    t.api.spawn({ type: "ground", x: -200, y: 400, w: 1200, h: 48, solid: true, gravityScale: 0 });
    t.step(5);
    t.expect(t.api.byType("jetpack").length === 1, "one jetpack");
    t.expect(!!t.api.hud("jetpack-fuel"), "fuel HUD is shown");
  },
};

export default {
  id: "rideable-dragon",
  title: "Rideable Dragon",
  knobs: { speed: { value: 260, min: 80, max: 500, label: "Flight speed" } },
  setup(api: any, knobs: any) {
    const speed = Number(knobs.speed) || 260;
    const dragon: any = api.spawn({ type: "dragon", x: 180, y: 180, w: 84, h: 52, solid: false, gravityScale: 0, color: 0x3fae4a, data: { flying: true, mounted: false } });
    let mounted = false;
    api.onTick((dt: number) => {
      const p: any = api.player();
      if (!p) return;
      if (!mounted && api.touches(p, dragon)) { mounted = true; dragon.data.mounted = true; api.say(dragon, "Hold on!", 2); }
      if (!mounted) return;
      let vx = 0;
      if (api.input().left) vx -= speed;
      if (api.input().right) vx += speed;
      dragon.x += vx * dt;
      p.x = dragon.x + dragon.w / 2 - p.w / 2;
      p.y = dragon.y - p.h + 10;
      p.vx = 0;
      p.vy = 0;
    });
  },
  dispose(api: any) {
    for (const e of api.byType("dragon")) api.despawn(e.id);
  },
  test(t: any) {
    t.api.spawn({ type: "ground", x: -200, y: 400, w: 1200, h: 48, solid: true, gravityScale: 0 });
    t.step(5);
    t.expect(t.api.byType("dragon").length === 1, "one dragon");
  },
};
